TEST("powers") { CHECK_EQ(power(2, 10), 1024LL); CHECK_EQ(power(3, 0), 1LL); CHECK_EQ(power(-2, 3), -8LL); CHECK_EQ(power(10, 15), 1000000000000000LL); }
TEST("factorials") { CHECK_EQ(factorial(0), 1LL); CHECK_EQ(factorial(1), 1LL); CHECK_EQ(factorial(5), 120LL); CHECK_EQ(factorial(20), 2432902008176640000LL); }
TEST("choosing") { CHECK_EQ(choose(5, 2), 10LL); CHECK_EQ(choose(10, 0), 1LL); CHECK_EQ(choose(10, 10), 1LL); CHECK_EQ(choose(20, 10), 184756LL); CHECK_EQ(choose(4, 5), 0LL); CHECK_EQ(choose(4, -1), 0LL); }
TEST("clamping") { CHECK_EQ(clamp(5, 0, 10), 5); CHECK_EQ(clamp(-3, 0, 10), 0); CHECK_EQ(clamp(99, 0, 10), 10); CHECK_EQ(clamp(0, 0, 10), 0); }

